@@ -0,0 +1,73 @@
+/*
+* Safeguarding test for: fix(pictorialBar): symbol should not flip with zero data
+* (mirrors apache/echarts PR #20260)
+*
+* A zero-valued pictorial bar must not get a special-case pxSign flip: it keeps
+* the default symbol direction, while nearby positive and negative values still
+* render with their intended orientation rules.
+*/
+
+import { EChartsType } from '../src/echarts';
+import { createChart } from '../test/ut/core/utHelper';
+
+describe('pictorialbar-zero-symbol-flip', function () {
+
+    let chart: EChartsType;
+    afterEach(function () {
+        chart && chart.dispose();
+    });
+
+    const PATH_SYMBOL = 'path://M0,0 L10,0 L10,10 L0,10 Z';
+
+    function getPxSigns(horizontal: boolean, inverse: boolean, data: number[]): number[] {
+        chart = createChart({ width: 600, height: 400 });
+
+        const catAxis = {
+            type: 'category' as const,
+            data: data.map(function (_, idx) { return 'c' + idx; })
+        };
+        const valueAxis = {
+            type: 'value' as const,
+            inverse: inverse
+        };
+
+        chart.setOption({
+            xAxis: horizontal ? valueAxis : catAxis,
+            yAxis: horizontal ? catAxis : valueAxis,
+            series: [{
+                type: 'pictorialBar',
+                symbol: PATH_SYMBOL,
+                symbolSize: 30,
+                animation: false,
+                data: data
+            }]
+        });
+
+        const view = (chart as any)._chartsViews[0];
+        return view.group.children().map(function (bar: any) {
+            return bar.__pictorialSymbolMeta.pxSign;
+        });
+    }
+
+    it('zero value does not introduce a special-case flip', function () {
+        // Positive and zero bars must share the same pxSign; the negative bar
+        // keeps its intended flipped orientation.
+        const pxSigns = getPxSigns(true, false, [10, 0, -10]);
+        expect(pxSigns.length).toBe(3);
+        expect(pxSigns[1]).toBe(pxSigns[0]); // zero == positive
+        expect(pxSigns[2]).toBe(-pxSigns[0]); // negative still flipped as intended
+    });
+
+    it('positive and negative values keep their orientation rules around zero', function () {
+        const pxSigns = getPxSigns(false, false, [-10, 0, 10]);
+        expect(pxSigns.length).toBe(3);
+        expect(pxSigns[1]).toBe(pxSigns[2]); // zero == positive
+        expect(pxSigns[0]).toBe(-pxSigns[2]); // negative still flipped as intended
+    });
+
+    it('all-zero series keeps a stable default direction', function () {
+        const pxSigns = getPxSigns(true, false, [0, 0]);
+        expect(pxSigns.length).toBe(2);
+        expect(pxSigns[0]).toBe(pxSigns[1]);
+    });
+});
